import maya.cmds as cmds

def prepare_for_substance():
    # Renombrar objetos seleccionados con sufijo _low para horneado en Substance
    selected = cmds.ls(sl=True, long=True) or []
    for obj_path in selected:
        obj = obj_path.split('|')[-1]
        if not obj.endswith('_low'):
            cmds.rename(obj_path, f'{obj}_low')
    print('Mallas preparadas con sufijos _low para Substance Painter.')
